// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "deposit failed");

        vm.prank(user);
        try c.withdraw() {
            assertTrue(c.balances(user) == 0 && address(user).balance == 1 ether);
        } catch {
            assertTrue(c.balances(user) == 0 && address(user).balance == 0 ether);
        }
    }
}
